<template><view class="page"><view class="head row"><view><text class="eyebrow">企业中心</text><text class="title">合作学校</text></view><view class="primary-btn add-btn" @tap="addSchool">＋ 新增</view></view><view v-if="schools.length" class="school-list"><view v-for="(school,index) in schools" :key="school.id" class="school-card card"><view class="row"><view><text class="school-name">{{school.name}}</text><text class="muted">合作中 · {{school.activities}} 场活动</text></view><text class="remove" @tap="removeSchool(index)">删除</text></view><text class="school-detail">触达学生 {{school.students}} 人次 · 合作开始于 {{school.date}}</text></view></view><view v-else class="empty card">暂无合作学校，点击右上角新增。</view></view></template>
<script>import {toast} from '../../common/mock.js';const key='enterprise_schools';const defaultSchools=[{id:1,name:'安徽理工大学',activities:6,students:'12,680',date:'2026-03-12'}];export default{data(){return{schools:[]}},onShow(){this.loadSchools()},methods:{loadSchools(){this.schools=uni.getStorageSync(key)||defaultSchools.map(item=>({...item}))},saveSchools(){uni.setStorageSync(key,this.schools)},addSchool(){uni.showModal({title:'新增合作学校',editable:true,placeholderText:'请输入学校名称',success:res=>{if(res.confirm&&res.content){this.schools.push({id:Date.now(),name:res.content,activities:0,students:0,date:'2026-08-20'});this.saveSchools();toast('学校已添加')}}})},removeSchool(index){uni.showModal({title:'确认删除该合作学校？',success:res=>{if(res.confirm){this.schools.splice(index,1);this.saveSchools();toast('已删除')}}})}}}</script>
<style lang="scss">@import '../../common/portal.scss';.add-btn{min-height:60rpx;padding:0 20rpx;font-size:22rpx}.school-card{margin-bottom:20rpx}.school-name{display:block;color:#181c1c;font-size:29rpx;font-weight:700}.school-card .remove{color:#ba1a1a;font-size:22rpx}.school-detail{display:block;margin-top:20rpx;color:#53615f;font-size:23rpx}.empty{text-align:center;color:#6d7a6e;font-size:25rpx}</style>
